CategoryTheory.NatTrans.ext  ∀ {C : Type u₁} {inst : CategoryTheory.Category.{v₁, u₁} C} {D : Type u₂} {inst_1 : CategoryTheory.Category.{v₂, u₂} D}
  {F G : CategoryTheory.Functor C D} {x y : CategoryTheory.NatTrans F G}, x.app = y.app → x = y  -- Extensionality Lemma for Natural Transformations
CategoryTheory.NatTrans.ext_iff  ∀ {C : Type u₁} {inst : CategoryTheory.Category.{v₁, u₁} C} {D : Type u₂} {inst_1 : CategoryTheory.Category.{v₂, u₂} D}
  {F G : CategoryTheory.Functor C D} {x y : CategoryTheory.NatTrans F G}, x = y ↔ x.app = y.app  -- Extensionality of Natural Transformations
CategoryTheory.Functor.HomObj.ext_iff  ∀ {C : Type u} {inst : CategoryTheory.Category.{v, u} C} {D : Type u'} {inst_1 : CategoryTheory.Category.{v', u'} D}
  {F G : CategoryTheory.Functor C D} {A : CategoryTheory.Functor C (Type w)} {x y : F.HomObj G A}, x = y ↔ x.app = y.app  -- Extensionality of Natural Transformations
CategoryTheory.Quotient.natTrans_ext  {F G : Quotient r ⥤ D} (τ₁ τ₂ : F ⟶ G)
  (h : whiskerLeft (Quotient.functor r) τ₁ = whiskerLeft (Quotient.functor r) τ₂) : τ₁ = τ₂  -- Extensionality of Natural Transformations in Quotient Categories
CategoryTheory.SingleFunctors.hom_ext  (f g : F ⟶ G) (h : f.hom = g.hom) : f = g  -- Extensionality for Natural Transformations Between SingleFunctors

